// Rows in the results tab whose status is STATUS_IN ("excellent").
const g = $('Globals').first().json;
// REDO_RESTYLED = true: pick rows already at STATUS_OUT instead; Load Old HTML
// then only keeps the ones whose HTML already has the pill (i.e. were restyled).
const want = String(g.REDO_RESTYLED ? g.STATUS_OUT : g.STATUS_IN).trim().toLowerCase();
const rows = $input.all().map((i) => i.json)
  .filter((r) => String(r.status || '').trim().toLowerCase() === want);
if (rows.length === 0) return [{ json: { _empty: true } }];
return rows.slice(0, g.BATCH_SIZE || rows.length).map((r) => ({ json: r }));

// Everything that came back through the loop, counted.
const g = $('Globals').first().json;
const all = $input.all().map((i) => i.json);
const skipped = all.filter((r) => r.result === 'skipped');
const done = all.filter((r) => r.result !== 'skipped');
return [{
  json: {
    restyled: done.length,
    skipped: skipped.length,
    skipped_rows: skipped.map((r) => `${r.row_key}: ${r.reason}`),
    note: skipped.length
      ? `Skipped rows keep their status and will be retried next run.`
      : 'All selected rows restyled.',
  },
}];

// Finds carousel_post<N>.html in the row's folder and builds the pill prompt.
// Nothing is changed on disk here.
const fs = require('fs');
const g = $('Globals').first().json;
const row = $json;

const root = String(g.LOCAL_OUTPUT_ROOT || '').replace(/[\\/]+$/, '');
const folder = String(row.folder_name || '').trim();
const postIndex = parseInt(row.post_index, 10) || 1;
const dir = `${root}/${folder}`;

let problem = null;
let htmlFile = null;
if (!root) problem = 'LOCAL_OUTPUT_ROOT is empty in Globals';
else if (!folder) problem = 'folder_name is empty';
else if (/[\\/]|\.\./.test(folder)) problem = `folder_name looks like a path: ${folder}`;
else if (!fs.existsSync(dir)) problem = `folder not found: ${dir}`;
else {
  const want = `carousel_post${postIndex}.html`;
  const files = fs.readdirSync(dir);
  if (files.includes(want)) htmlFile = want;
  else {
    const any = files.filter((f) => /^carousel_post\d+\.html$/.test(f));
    if (any.length === 1) htmlFile = any[0];
    else problem = any.length
      ? `several carousel_post*.html in ${dir}, none for post ${postIndex}`
      : `no carousel_post*.html in ${dir}`;
  }
}

if (problem) {
  return [{ json: { found: false, row_key: row.row_key, folder_name: folder, reason: problem } }];
}

const html = fs.readFileSync(`${dir}/${htmlFile}`, 'utf8');

// A pill already in the HTML means this carousel was restyled before.
const pillMatch = html.match(/<div class="pill"><span class="pill-dot"><\/span>([\s\S]*?)<\/div>/);
const existing_pill_label = pillMatch
  ? pillMatch[1].replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim()
  : '';
if (g.REDO_RESTYLED && !existing_pill_label) {
  return [{ json: { found: false, row_key: row.row_key, folder_name: folder,
    reason: 'redo mode: HTML has no pill, so it was never restyled (left alone)' } }];
}

// Hook slide text, stripped of tags, to give the pill label some context.
const plain = (s) => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&')
  .replace(/&[a-z]+;/g, ' ').replace(/\s+/g, ' ').trim();
const hook = (html.match(/<div class="slide slide--hook[\s\S]*?<div class="footer">/) || [''])[0];
const hookHeadline = plain((hook.match(/<h1 class="headline">([\s\S]*?)<\/h1>/) || [])[1]);
const hookText = plain((hook.match(/<div class="blocks">([\s\S]*?)<\/div>\s*<\/div>/) || [])[1]);

const pill_prompt = `Write the label for a small pill badge on the first slide of an Instagram carousel about a research paper. The label names the TOPIC of the study in 2 or 3 words, like a tag. Examples of the style: "Pilot studies", "Sleep and memory", "Trust in robots".

Rules:
- 2 or 3 words, at most 24 characters.
- Sentence case: capitalise only the first word and proper nouns.
- Plain everyday words a 17 year old understands. No jargon.
- Name the topic, not the finding. Do not repeat the headline.
- No quotes, no punctuation, no emoji, no hashtags, no dashes.

Paper title: ${row.title || ''}
Post angle: ${row.angle_label || ''}
Hook headline: ${hookHeadline}
Hook text: ${hookText}

Reply with the label only.`;

return [{
  json: {
    found: true,
    row_key: row.row_key,
    title: row.title,
    angle_label: row.angle_label,
    folder_name: folder,
    dir,
    html_file: htmlFile,
    post_index: postIndex,
    html,
    existing_pill_label,
    pill_prompt,
  },
}];

// ============================================================================
//  Restyle HTML — applies the blue house style to the old carousel HTML.
//  Text, blocks and layout of every slide stay exactly as they were.
// ============================================================================

// ============================================================================
//  restyle(html, opts)  —  red carousel HTML  ->  blue house style.
//  Pure string transform: every slide's text, blocks and layout stay exactly
//  as they are. Only these things change:
//    1. red palette tokens -> blue (accent, neg, payoff slide colours)
//    2. every logo -> the blue logo
//    3. footer -> two-line programme handle (CSS + markup)
//    4. CTA slide text: old faculty name -> programme names
//    5. pill CSS + a pill with a 2-3 word label on the hook slide
//  Idempotent: running it on an already-blue file gives the same file.
// ============================================================================

const COLOR_MAP = {
  '#c72125': '#008EAA', // accent / neg / payoff background
  '#f6d5d6': '#6dd9ff', // payoff muted
  '#b31d21': '#006a88', // payoff surface
  '#a01a1d': '#005273', // payoff surface-2
  '#d4585b': '#1ba8c9', // payoff line
};

const FOOTER_CSS =
  '.footer { display:flex; justify-content:space-between; align-items:flex-start;' +
  ' padding-top:34px; }';
const FOOTER_LEFT_CSS = '.footer-left { display:flex; flex-direction:column; gap:8px; }';

const PILL_CSS =
  '.pill { display:inline-flex; align-items:center; gap:10px; background:#008EAA;' +
  ' color:#ffffff; padding:14px 28px; border-radius:28px;' +
  ' font-family:var(--font-display); font-weight:700; font-size:32px;' +
  ' letter-spacing:.04em; position:absolute; top:140px; left:84px; }\n' +
  '  .pill-dot { width:8px; height:8px; background:#ffffff; border-radius:50%; }\n' +
  '  .slide--hook .pill { background:#008EAA; color:#ffffff; }\n  ';

const escHtml = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function restyle(html, opts) {
  const { pillLabel, logoUrl, handles, oldFacultyName, ctaName } = opts;
  let out = String(html);
  const changes = [];

  // ---- split style from body so CSS edits never touch slide text ----------
  const m = out.match(/^([\s\S]*?<style>)([\s\S]*?)(<\/style>[\s\S]*)$/);
  if (!m) throw new Error('No <style> block found in HTML');
  let [, head, css, rest] = m;

  // 1. palette
  for (const [from, to] of Object.entries(COLOR_MAP)) {
    const re = new RegExp(from, 'gi');
    if (re.test(css)) { css = css.replace(re, to); changes.push(`colour ${from}->${to}`); }
  }

  // 3a. footer CSS
  css = css.replace(/\.footer\s*\{[^}]*\}/, FOOTER_CSS);
  if (!/\.footer-left\s*\{/.test(css)) {
    css = css.replace(FOOTER_CSS, FOOTER_CSS + '\n  ' + FOOTER_LEFT_CSS);
    changes.push('footer-left css added');
  }

  // 5a. pill CSS (once), placed before the per-type variants like the template
  if (!/\.pill\s*\{/.test(css)) {
    const anchor = css.search(/\/\*\s*-+\s*per-type variants|\.slide--hook,\s*\.slide--cta\s*\{/);
    css = anchor >= 0 ? css.slice(0, anchor) + PILL_CSS + css.slice(anchor) : css + '\n  ' + PILL_CSS;
    changes.push('pill css added');
  }

  let body = rest;

  // 2. logos: every logo image (and any placeholder) -> blue logo
  const logoImg = `<img class="logo-img" src="${escHtml(logoUrl)}" alt="TU/e">`;
  body = body.replace(/<img class="logo-img"[^>]*>/g, logoImg);
  body = body.replace(/<span class="logo-ph">[\s\S]*?<\/span>/g, logoImg);

  // 3b. footer markup: whatever sits before footer-right becomes the two handles
  const left = '<div class="footer-left">' +
    handles.map((h) => `<span class="handle">${escHtml(h)}</span>`).join('') + '</div>';
  let footers = 0;
  body = body.replace(/(<div class="footer">)[\s\S]*?(<div class="footer-right">)/g, (_, a, b) => {
    footers++; return a + left + b;
  });

  // 4. CTA text: old faculty name -> programme names (CTA slide only)
  if (oldFacultyName && ctaName) {
    body = body.replace(
      /(<div class="slide slide--cta[^"]*">)([\s\S]*?)(<div class="footer">)/,
      (_, a, content, c) => {
        const re = new RegExp(oldFacultyName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
        if (re.test(content)) changes.push('cta faculty name replaced');
        return a + content.replace(re, escHtml(ctaName)) + c;
      }
    );
  }

  // 5b. pill on the hook slide (replace an existing pill if re-run)
  body = body.replace(/<div class="pill">[\s\S]*?<\/div>/g, '');
  let pills = 0;
  body = body.replace(/(<div class="slide slide--hook[^"]*">)/, (a) => {
    pills++;
    return a + `<div class="pill"><span class="pill-dot"></span>${escHtml(pillLabel)}</div>`;
  });
  if (!pills) throw new Error('No hook slide found for the pill');

  const slides = (body.match(/<div class="slide slide--/g) || []).length;
  if (footers !== slides) throw new Error(`Footer rewrite hit ${footers} of ${slides} slides`);

  return { html: head + css + body, slides, changes };
}

// ============================================================================
//  n8n GLUE
// ============================================================================
const g = $('Globals').first().json;
const src = $('Load Old HTML').first().json;

// Clean up whatever Haiku returned; fall back to the angle label if unusable.
function cleanLabel(s) {
  const line = String(s || '').split(/\r?\n/).map((l) => l.trim()).filter(Boolean)[0] || '';
  return line
    .replace(/^label\s*:\s*/i, '')
    .replace(/[—–-]/g, ' ')
    .replace(/[^\p{L}\p{N}&' ]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
}
// A carousel that already has a pill keeps its label (a redo only fixes the
// style); new ones get Haiku's label.
let pillLabel = src.existing_pill_label || cleanLabel($json.output);
let pillWarning = '';
const words = pillLabel.split(' ').filter(Boolean);
if (words.length < 1 || words.length > 3 || pillLabel.length > 28) {
  const fallback = cleanLabel(src.angle_label).split(' ').slice(0, 3).join(' ');
  pillWarning = `pill label "${pillLabel}" unusable, used "${fallback}"`;
  pillLabel = fallback;
}
if (!pillLabel) throw new Error(`No usable pill label for ${src.row_key}`);
pillLabel = pillLabel.charAt(0).toUpperCase() + pillLabel.slice(1);

const result = restyle(src.html, {
  pillLabel,
  logoUrl: g.LOGO_URL_BLUE,
  handles: [g.HANDLE_LINE_1, g.HANDLE_LINE_2].filter(Boolean),
  oldFacultyName: g.OLD_FACULTY_NAME,
  ctaName: g.CTA_PROGRAMME_NAME,
});

return [{
  json: {
    row_key: src.row_key,
    dir: src.dir,
    folder_name: src.folder_name,
    html_file: src.html_file,
    total_slides: result.slides,
    pill_label: pillLabel,
    pill_warning: pillWarning,
    changes: result.changes,
    html: result.html,
  },
}];

// ============================================================================
//  Save New Slides — only runs after the renderer succeeded, so a failed
//  render never leaves a folder empty.
//  1. decode + validate every new slide in memory
//  2. clear the folder, keeping concept_post*.json
//  3. write slide_NN.jpg + the restyled carousel_post<N>.html
// ============================================================================
const fs = require('fs');
const g = $('Globals').first().json;
const src = $('Restyle HTML').first().json;
const resp = $json;

const images = resp.images || [];
const urls = Array.isArray(resp.urls) ? resp.urls : [];
if (images.length !== src.total_slides) {
  throw new Error(`Renderer returned ${images.length} images, expected ${src.total_slides} (${src.row_key})`);
}
if (urls.length !== src.total_slides) {
  throw new Error(`Renderer returned ${urls.length} urls, expected ${src.total_slides}. Is PUBLIC_BASE_URL set on carousel-renderer?`);
}

// 1. decode first
const slides = images.map((img, i) => {
  const b64 = typeof img === 'string' ? img : (img.image_base64 || img.base64 || img.data);
  if (!b64) throw new Error(`No image data for slide ${i + 1} (${src.row_key})`);
  const buf = Buffer.from(b64, 'base64');
  if (buf.length < 1000) throw new Error(`Slide ${i + 1} is suspiciously small (${buf.length} bytes)`);
  return { name: `slide_${String(i + 1).padStart(2, '0')}.jpg`, buf };
});

// 2. clear the folder (safety: must be a direct child of LOCAL_OUTPUT_ROOT)
const root = String(g.LOCAL_OUTPUT_ROOT || '').replace(/[\\/]+$/, '');
const dir = src.dir;
if (!root || dir !== `${root}/${src.folder_name}` || !src.folder_name || /[\\/]|\.\./.test(src.folder_name)) {
  throw new Error(`Refusing to clear unexpected folder: ${dir}`);
}
const KEEP = /^concept_post\d+\.json$/;
const deleted = [];
for (const f of fs.readdirSync(dir)) {
  if (KEEP.test(f)) continue;
  fs.rmSync(`${dir}/${f}`, { recursive: true, force: true });
  deleted.push(f);
}

// 3. write the new files
for (const s of slides) fs.writeFileSync(`${dir}/${s.name}`, s.buf);
fs.writeFileSync(`${dir}/${src.html_file}`, src.html, 'utf8');

return [{
  json: {
    row_key: src.row_key,
    folder_name: src.folder_name,
    slide_urls: urls.join('\n'),
    pill_label: src.pill_label,
    pill_warning: src.pill_warning,
    written: [...slides.map((s) => s.name), src.html_file],
    deleted,
  },
}];
